  let ui: StatusUi | null = null;
  let revision = 0;
  let lastDigest = "";
  /** Set only by a probe that failed; null means the bridge can drive vibe. */
  let broken: string | null = null;
  /** Module-resolution failures, keyed by import; non-empty wins availability. */
  const importFailures = new Map<string, string>();
  /** The tools mounted by the last enter; empty whenever the mode is off. */
  const mounted = new Map<string, ToolLike>();
